svg.script:
(function () {
  var svg = document.documentElement, NS = 'http://www.w3.org/2000/svg';

  /* ---------- 1. SENDI: pivot [x,y] dalam koordinat induknya ---------- */
  var JOINTS = {
    root:[505,1040], torso:[505,1030], head:[500,675],
    armL:[352,738],  foreL:[335,890],
    armR:[650,738],  foreR:[673,892],
    thighL:[437,1040], shinL:[448,1340], footL:[452,1600],
    thighR:[587,1040], shinR:[600,1320], footR:[610,1560]
  };
  var el = {}; for (var k in JOINTS) el[k] = document.getElementById('j-' + k);

  /* ---------- 2. HOTSPOT luka menempel ke sendi ---------- */
  var HS = [ // id, sendi, x, y, glow, delay
    ['kepala','head',484,486,54,2.2], ['mata','head',528,564,0,2.45], ['telinga','head',574,570,46,2.7], ['wajah','head',556,618,46,2.95],
    ['perut','torso',482,906,72,3.2], ['panggul','torso',352,1052,62,3.45],
    ['tangan','foreR',696,1078,58,3.7], ['kaki','thighL',448,1288,64,3.95], ['gelang','shinL',452,1607,52,4.2]
  ];
  var layer = document.getElementById('hotspots');
  function mk(tag, attrs, parent) { var n = document.createElementNS(NS, tag); for (var a in attrs) n.setAttribute(a, attrs[a]); (parent || layer).appendChild(n); return n; }
  var hsEl = {};
  HS.forEach(function (h) {
    var g = mk('g', {id:'hs-' + h[0]});
    if (h[4]) { var gg = mk('g', {'class':'pop', style:'--d:' + h[5] + 's'}, g); mk('circle', {'class':'throb', r:h[4], fill:'url(#wound)'}, gg); }
    var c = mk('g', {'class':'pop', style:'--d:' + h[5] + 's'}, g);
    mk('circle', {'class':'ring pulse', r:14, style:'--d:' + h[5] + 's'}, c);
    mk('circle', {r:14, fill:'#2a1a12', stroke:'#e0b86a', 'stroke-width':3}, c);
    mk('circle', {r:5, fill:'#e0b86a'}, c);
    hsEl[h[0]] = g;
  });
  var callouts = [].slice.call(document.querySelectorAll('#callouts path[data-hs]'));
  var P = {};
  function updateAttach() {
    var inv = layer.getCTM().inverse();
    HS.forEach(function (h) {
      var m = inv.multiply(el[h[1]].getCTM());
      var p = new DOMPoint(h[2], h[3]).matrixTransform(m);
      P[h[0]] = p; hsEl[h[0]].setAttribute('transform', 'translate(' + p.x.toFixed(2) + ' ' + p.y.toFixed(2) + ')');
    });
    callouts.forEach(function (c) {
      var p = P[c.dataset.hs];
      c.setAttribute('d', 'M' + p.x.toFixed(2) + ' ' + p.y.toFixed(2) + ' L' + c.dataset.x2 + ' ' + c.dataset.y2);
    });
  }

  /* ---------- 3. POSE: {sendi: derajat, dx, dy, br(napas)} ---------- */
  function apply(p) {
    for (var k in JOINTS) {
      var c = JOINTS[k], a = p[k] || 0, t;
      if (k === 'root') t = 'translate(' + (p.dx || 0) + ' ' + (p.dy || 0) + ')';
      else if (k === 'torso') t = 'rotate(' + a + ' ' + c[0] + ' ' + c[1] + ') translate(' + c[0] + ' ' + c[1] + ') scale(1 ' + (p.br || 1) + ') translate(' + (-c[0]) + ' ' + (-c[1]) + ')';
      else t = 'rotate(' + a + ' ' + c[0] + ' ' + c[1] + ')';
      el[k].setAttribute('transform', t);
    }
    updateAttach();
  }

  /* ---------- 4. DEMO 5 detik (keyframe + easing) ---------- */
  function kf(t, pts) {
    if (t <= pts[0][0]) return pts[0][1];
    for (var i = 1; i < pts.length; i++) if (t <= pts[i][0]) {
      var a = pts[i-1], b = pts[i], u = (t - a[0]) / (b[0] - a[0]), e = u < .5 ? 2*u*u : 1 - 2*(1-u)*(1-u);
      return a[1] + (b[1] - a[1]) * e;
    }
    return pts[pts.length-1][1];
  }
  var DUR = 5;
  function demo(t) {
    var b = Math.sin(t * Math.PI * 2 / 2.5);
    var thL = kf(t, [[0,0],[.5,0],[1.2,5],[2,0],[3.2,0],[3.7,-3],[4.4,0]]);
    var thR = kf(t, [[0,0],[.5,0],[1.2,-4],[2,0],[3.2,0],[3.7,3],[4.4,0]]);
    return {
      dy: 2 * b + kf(t, [[0,0],[3.5,0],[3.75,5],[4.0,0],[4.25,5],[4.5,0]]),
      br: 1 + .007 * b,
      torso: kf(t, [[0,0],[.4,0],[1.2,-2.5],[2.2,-2.5],[3,0],[3.8,2],[4.6,0]]),
      head:  kf(t, [[0,0],[.3,0],[1,11],[1.5,11],[2.1,-10],[2.6,-10],[3.1,0],[3.8,6],[4.6,0]]),
      armL:  kf(t, [[0,0],[1.6,0],[2.4,80],[3.6,80],[4.5,0]]),
      foreL: kf(t, [[0,0],[1.6,0],[2.4,145],[3.6,145],[4.5,0]]),
      armR:  kf(t, [[0,0],[.6,-4],[1.4,0],[2.2,-6],[3,0],[3.8,-8],[4.6,0]]),
      foreR: kf(t, [[0,0],[1,-8],[2,0],[3,-10],[4,0]]),
      thighL: thL, shinL: -thL * .9 + kf(t, [[0,0],[3.5,0],[3.75,4],[4,0],[4.25,4],[4.5,0]]), footL: kf(t, [[0,0],[1.2,-3],[2,0]]),
      thighR: thR, shinR: -thR * .9 + kf(t, [[0,0],[3.5,0],[3.75,4],[4,0],[4.25,4],[4.5,0]]), footR: kf(t, [[0,0],[1.2,3],[2,0]])
    };
  }

  /* ---------- 5. Loop + drag sendi dengan mouse/jari ---------- */
  var cur = demo(0), auto = !window.__capture, T0 = performance.now();
  window.__rig = { apply: apply, demo: demo, DUR: DUR, JOINTS: JOINTS };
  window.setRigTime = function (t) { apply(demo(t)); };
  window.resetRig = function () { auto = true; T0 = performance.now(); };

  function loop() { if (auto) { cur = demo(((performance.now() - T0) / 1000) % (DUR + 1)); apply(cur); } requestAnimationFrame(loop); }
  apply(cur);
  if (!window.__capture) requestAnimationFrame(loop);

  var drag = null;
  function ang(g, e, c) {
    var inv = g.parentNode.getScreenCTM().inverse(), p = new DOMPoint(e.clientX, e.clientY).matrixTransform(inv);
    return Math.atan2(p.y - c[1], p.x - c[0]) * 180 / Math.PI;
  }
  svg.addEventListener('pointerdown', function (e) {
    var g = e.target.closest && e.target.closest('[data-j]'); if (!g) return;
    var k = g.dataset.j; auto = false; svg.setPointerCapture(e.pointerId);
    drag = { k: k, g: g, a0: ang(g, e, JOINTS[k]), v0: cur[k] || 0 };
  });
  svg.addEventListener('pointermove', function (e) {
    if (!drag) return; var d = ang(drag.g, e, JOINTS[drag.k]) - drag.a0;
    if (d > 180) d -= 360; if (d < -180) d += 360;
    cur[drag.k] = drag.v0 + d; apply(cur);
  });
  svg.addEventListener('pointerup', function () { drag = null; });
  svg.addEventListener('dblclick', function () { window.resetRig(); });
})();
